import { test, expect } from '@playwright/test';

test.describe('Payment Flow', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/payment');
  });

  test('should display loading state during payment processing', async ({ page }) => {
    await page.fill(getByLabel('Card Number'), '4111 1111 1111 1111');
    await page.fill(getByLabel('Expiry Date'), '12/23');
    await page.fill(getByLabel('CVC'), '123');
    await page.click(getByRole('button', { name: 'Pay Now' }));

    const loadingIndicator = page.getByText('Processing your payment...');
    await expect(loadingIndicator).toBeVisible();
  });

  test('should hide loading state after payment processing', async ({ page }) => {
    await page.fill(getByLabel('Card Number'), '4111 1111 1111 1111');
    await page.fill(getByLabel('Expiry Date'), '12/23');
    await page.fill(getByLabel('CVC'), '123');
    await page.click(getByRole('button', { name: 'Pay Now' }));

    const loadingIndicator = page.getByText('Processing your payment...');
    await expect(loadingIndicator).toBeVisible();

    // Simulate payment processing completion
    await page.waitForTimeout(3000); // Adjust time as necessary for the test

    await expect(loadingIndicator).not.toBeVisible();
    await expect(page.getByText('Payment Successful')).toBeVisible();
  });
});
